"""Sparse, hybrid, and reranked retrieval strategies."""import refrom typing import List, Dictfrom rank_bm25 import BM25Okapifrom src.store import VectorStoredef tokenize(text: str) -> List[str]:    return re.findall(r"[a-z0-9]+", text.lower())class BM25Retriever:    """Sparse keyword retrieval over the same chunks held in Chroma."""    def __init__(self, store: VectorStore):        data = store.collection.get()        self.ids = data["ids"]        self.docs = data["documents"]        self.meta = data["metadatas"]        self.bm25 = BM25Okapi([tokenize(d) for d in self.docs])    def search(self, query: str, k: int = 5) -> List[Dict]:        scores = self.bm25.get_scores(tokenize(query))        order = sorted(range(len(scores)), key=lambda i: scores[i], reverse=True)[:k]        return [{            "id": self.ids[i],            "text": self.docs[i],            "source": self.meta[i]["source"],            "chunk_index": self.meta[i]["chunk_index"],            "similarity": float(scores[i]),        } for i in order]def reciprocal_rank_fusion(runs: List[List[Dict]], k: int = 5,                           rrf_k: int = 10) -> List[Dict]:    """    Merge ranked lists by rank, not score.    Score scales differ between dense cosine and BM25, so score-based fusion    is meaningless. RRF gives each doc 1/(rrf_k + rank) per list and sums.    NOTE: rrf_k=60 is the value from the original RRF paper, tuned for merging    over web-scale corpora. On a 188-chunk index with 20-item candidate lists    it flattens rank differences so severely that a document ranked mid-list in    BOTH runs outscores one ranked first in a single run. Lowered to 10.    """    scores, docs = {}, {}    for run in runs:        for rank, hit in enumerate(run, start=1):            scores[hit["id"]] = scores.get(hit["id"], 0.0) + 1.0 / (rrf_k + rank)            docs.setdefault(hit["id"], hit)    best = sorted(scores, key=lambda i: scores[i], reverse=True)[:k]    out = []    for doc_id in best:        hit = dict(docs[doc_id])        hit["similarity"] = scores[doc_id]        out.append(hit)    return outclass HybridRetriever:    """Dense + BM25, fused with RRF."""    def __init__(self, store: VectorStore, candidates: int = 20, rrf_k: int = 10):        self.store = store        self.bm25 = BM25Retriever(store)        self.candidates = candidates        self.rrf_k = rrf_k    def search(self, query: str, k: int = 5) -> List[Dict]:        dense = self.store.search(query, k=self.candidates)        sparse = self.bm25.search(query, k=self.candidates)        return reciprocal_rank_fusion([dense, sparse], k=k, rrf_k=self.rrf_k)class RerankRetriever:    """    Retrieve a wide candidate set cheaply, then rerank with a cross-encoder.    The bi-encoder embeds query and chunk separately. A cross-encoder reads    both together, so attention runs across the pair - much more accurate,    much too slow to apply to the whole corpus.    """    def __init__(self, base, candidates: int = 20,                 model_name: str = "cross-encoder/ms-marco-MiniLM-L-6-v2"):        from sentence_transformers import CrossEncoder        import torch        device = "mps" if torch.backends.mps.is_available() else "cpu"        self.model = CrossEncoder(model_name, device=device)        self.base = base        self.candidates = candidates    def search(self, query: str, k: int = 5) -> List[Dict]:        cands = self.base.search(query, k=self.candidates)        if not cands:            return []        pairs = [(query, c["text"]) for c in cands]        scores = self.model.predict(pairs)        order = sorted(range(len(cands)), key=lambda i: scores[i], reverse=True)[:k]        out = []        for i in order:            hit = dict(cands[i])            hit["similarity"] = float(scores[i])            out.append(hit)        return out